import { strict as assert } from "node:assert";
import { readFileSync } from "node:fs";
import { test } from "node:test";

const workflow = readFileSync(new URL("../.github/workflows/ci.yaml", import.meta.url), "utf8");

test("CI workflow uses least-privilege repository token permissions", () => {
  assert.match(workflow, /^permissions:\n {2}contents: read$/m);
  assert.doesNotMatch(workflow, /^permissions:\s*write-all$/m);
});

test("CI workflow pins third-party actions to immutable commit SHAs", () => {
  const actionRefs = [...workflow.matchAll(/^\s*uses:\s*([^@\s]+)@([^\s#]+)/gm)];

  assert.ok(actionRefs.length > 0, "expected workflow to use at least one action");

  for (const [, action, ref] of actionRefs) {
    assert.match(ref, /^[a-f0-9]{40}$/, `${action} is not pinned to a full commit SHA`);
  }
});

test("CI workflow checkout steps do not persist GitHub token credentials", () => {
  const checkoutBlocks = workflow
    .split(/\n(?=\s+- name: )/)
    .filter((block) => block.includes("uses: actions/checkout@"));

  assert.ok(checkoutBlocks.length > 0, "expected workflow to use checkout");

  for (const block of checkoutBlocks) {
    assert.match(block, /\n\s+persist-credentials:\s*false\b/);
  }
});

import { strict as assert } from "node:assert";
import { test } from "node:test";

process.env.DATABASE_URL ??= "postgres://localhost:5434/superlog";
const {
  parseMemoryKind,
  parseMemoryText,
  parseMemoryStatus,
  serializeAgentMemory,
  createAgentMemory,
  AGENT_MEMORY_TITLE_MAX_LEN,
  AGENT_MEMORY_BODY_MAX_LEN,
} = await import("./agent-memories-service.js");

test("parseMemoryKind accepts the four valid kinds and rejects others", () => {
  for (const kind of ["feedback", "terminology", "infra", "project"]) {
    assert.equal(parseMemoryKind(kind), kind);
  }
  assert.equal(parseMemoryKind("bogus"), null);
  assert.equal(parseMemoryKind(42), null);
  assert.equal(parseMemoryKind(undefined), null);
});

test("parseMemoryText trims, rejects empty, and clamps to maxLen", () => {
  assert.equal(parseMemoryText("  hello  ", 100), "hello");
  assert.equal(parseMemoryText("   ", 100), null);
  assert.equal(parseMemoryText(123, 100), null);
  assert.equal(parseMemoryText("x".repeat(50), 10)?.length, 10);
});

test("title/body max lengths are exported for the MCP schema", () => {
  assert.equal(AGENT_MEMORY_TITLE_MAX_LEN, 200);
  assert.equal(AGENT_MEMORY_BODY_MAX_LEN, 4000);
});

test("parseMemoryStatus only accepts active/archived", () => {
  assert.equal(parseMemoryStatus("active"), "active");
  assert.equal(parseMemoryStatus("archived"), "archived");
  assert.equal(parseMemoryStatus("deleted"), null);
  assert.equal(parseMemoryStatus(undefined), null);
});

test("createAgentMemory rejects an unattributed or doubly-attributed create", async () => {
  const base = { orgId: "o1", projectId: "p1", kind: "project" as const, title: "t", body: "b" };
  // The guard throws before any DB access, so these never open a connection.
  await assert.rejects(
    () => createAgentMemory(base),
    /exactly one of sourceUserId or sourceAgentRunId/,
  );
  await assert.rejects(
    () => createAgentMemory({ ...base, sourceUserId: "u1", sourceAgentRunId: "r1" }),
    /exactly one of sourceUserId or sourceAgentRunId/,
  );
});

test("serializeAgentMemory derives source from which provenance column is set", () => {
  const base = {
    id: "m1",
    orgId: "o1",
    projectId: "p1",
    kind: "infra" as const,
    title: "Checkout runs on ECS",
    body: "...",
    status: "active" as const,
    sourceAgentRunId: null,
    sourceUserId: null,
    lastUsedAt: null,
    createdAt: new Date("2026-06-27T00:00:00.000Z"),
    updatedAt: new Date("2026-06-27T00:00:00.000Z"),
  };

  assert.equal(serializeAgentMemory({ ...base, sourceAgentRunId: "run1" }).source, "agent");
  assert.equal(serializeAgentMemory({ ...base, sourceUserId: "user1" }).source, "user");
  assert.equal(serializeAgentMemory(base).source, null);

  const out = serializeAgentMemory(base);
  assert.deepEqual(out, {
    id: "m1",
    kind: "infra",
    projectId: "p1",
    title: "Checkout runs on ECS",
    body: "...",
    status: "active",
    source: null,
    createdAt: "2026-06-27T00:00:00.000Z",
    updatedAt: "2026-06-27T00:00:00.000Z",
  });
});

import "./project-mcp-test-env.js";
import assert from "node:assert/strict";
import { test } from "node:test";
import { detectProjectMcpAuth } from "./project-mcp-auth-detection.js";

test("MCP auth detection recognizes standards-based OAuth authorization code servers", async () => {
  const http = {
    discover: async () => ({
      authorizationServer: "https://auth.granola.example",
      authorizationEndpoint: "https://auth.granola.example/authorize",
      tokenEndpoint: "https://auth.granola.example/token",
      registrationEndpoint: "https://auth.granola.example/register",
      resource: "https://mcp.granola.example/mcp",
      codeChallengeMethods: ["S256"],
      grantTypes: ["authorization_code", "refresh_token"],
      scopesSupported: ["projects:read", "database:read"],
    }),
  };

  assert.deepEqual(await detectProjectMcpAuth("https://mcp.granola.example/mcp", http), {
    type: "oauth",
    grantType: "authorization_code",
    supportsDynamicRegistration: true,
    scopesSupported: ["projects:read", "database:read"],
  });
});

test("MCP auth detection stays unknown when the server does not publish OAuth metadata", async () => {
  const result = await detectProjectMcpAuth("https://mcp.example/mcp", {
    discover: async () => {
      throw new Error("OAuth metadata discovery failed");
    },
  });

  assert.deepEqual(result, { type: "unknown" });
});

test("MCP auth detection rejects authorization code servers without PKCE S256", async () => {
  const result = await detectProjectMcpAuth("https://mcp.example/mcp", {
    discover: async () => ({
      codeChallengeMethods: ["plain"],
      grantTypes: ["authorization_code"],
      registrationEndpoint: "https://auth.example/register",
    }),
  });

  assert.deepEqual(result, { type: "unknown" });
});

test("MCP auth detection stays unknown for unsupported OAuth grants", async () => {
  const result = await detectProjectMcpAuth("https://mcp.example/mcp", {
    discover: async () => ({
      codeChallengeMethods: ["S256"],
      grantTypes: ["urn:ietf:params:oauth:grant-type:device_code"],
      registrationEndpoint: null,
    }),
  });

  assert.deepEqual(result, { type: "unknown" });
});

test("MCP auth detection times out slow OAuth discovery", async () => {
  const result = await detectProjectMcpAuth(
    "https://mcp.example/mcp",
    {
      discover: async () => {
        await new Promise((resolve) => setTimeout(resolve, 50));
        return {
          codeChallengeMethods: ["S256"],
          grantTypes: ["authorization_code"],
          registrationEndpoint: null,
        };
      },
    },
    5,
  );

  assert.deepEqual(result, { type: "unknown" });
});

import "./project-mcp-test-env.js";
import assert from "node:assert/strict";
import { test } from "node:test";
import type { ProjectMcpServer, ProjectMcpServerRepository } from "@superlog/db";
import {
  type ProjectMcpOAuthAttempt,
  createFetchProjectMcpOAuthHttp,
  createProjectMcpOAuthService,
} from "./project-mcp-oauth.js";

function oauthServer(): ProjectMcpServer {
  const now = new Date("2026-07-14T10:00:00.000Z");
  return {
    id: "server-1",
    projectId: "project-1",
    name: "linear",
    displayName: "Linear",
    url: "https://linear.example/mcp",
    enabled: false,
    auth: {
      type: "oauth",
      grantType: "authorization_code",
      status: "pending",
      scopes: ["issues:read"],
      clientId: null,
      clientSecret: null,
      accessToken: null,
      refreshToken: null,
      expiresAt: null,
      tokenEndpoint: null,
      authorizationServer: null,
      resource: null,
    },
    trustedAt: now,
    trustedByUserId: "user-1",
    createdByUserId: "user-1",
    updatedByUserId: "user-1",
    createdAt: now,
    updatedAt: now,
  };
}

test("OAuth discovery rejects private destinations at the outbound request boundary", async () => {
  await assert.rejects(
    createFetchProjectMcpOAuthHttp().discover("https://127.0.0.1/mcp"),
    /not allowed/i,
  );
});

test("OAuth dynamic registration restricts the client to requested scopes", async () => {
  const registrationBodies: Record<string, unknown>[] = [];
  const fakeFetch = (async (_input: URL | string | Request, init?: RequestInit) => {
    registrationBodies.push(JSON.parse(String(init?.body)) as Record<string, unknown>);
    return new Response(JSON.stringify({ client_id: "dynamic-client" }), {
      status: 201,
      headers: { "content-type": "application/json" },
    });
  }) as unknown as typeof fetch;

  await createFetchProjectMcpOAuthHttp(fakeFetch).register(
    "https://auth.example/register",
    "https://api.superlog.sh/api/agent-mcp-oauth/callback",
    ["projects:read", "database:read"],
  );

  assert.equal(registrationBodies[0]?.scope, "projects:read database:read");
});

test("OAuth start uses discovery, dynamic registration, PKCE, and resource binding", async () => {
  let server = oauthServer();
  let attempt: ProjectMcpOAuthAttempt | null = null;
  const repository = {
    get: async () => server,
    update: async (next: ProjectMcpServer) => {
      server = next;
      return next;
    },
  } as unknown as ProjectMcpServerRepository;
  const service = createProjectMcpOAuthService({
    repository,
    attempts: {
      create: async (value) => {
        attempt = value;
      },
      consume: async () => null,
    },
    http: {
      discover: async () => ({
        authorizationServer: "https://auth.example",
        authorizationEndpoint: "https://auth.example/authorize",
        tokenEndpoint: "https://auth.example/token",
        registrationEndpoint: "https://auth.example/register",
        resource: "https://linear.example/mcp",
        codeChallengeMethods: ["S256"],
        grantTypes: ["authorization_code", "refresh_token"],
        scopesSupported: ["issues:read", "issues:write"],
      }),
      register: async () => ({
        clientId: "dynamic-client",
        clientSecret: null,
      }),
      exchange: async () => {
        throw new Error("not called");
      },
      refresh: async () => {
        throw new Error("not called");
      },
      clientCredentials: async () => {
        throw new Error("not called");
      },
    },
    randomToken: (() => {
      const values = ["state-value", "verifier-value"];
      return () => values.shift() ?? "unused";
    })(),
    now: () => new Date("2026-07-14T10:00:00.000Z"),
  });

  const result = await service.start({
    projectId: "project-1",
    serverId: "server-1",
    actorUserId: "user-1",
    redirectUri: "https://api.superlog.sh/api/agent-mcp-oauth/callback",
  });

  const url = new URL(result.authorizationUrl);
  assert.equal(url.searchParams.get("client_id"), "dynamic-client");
  assert.equal(url.searchParams.get("state"), "state-value");
  assert.equal(url.searchParams.get("code_challenge_method"), "S256");
  assert.equal(url.searchParams.get("resource"), "https://linear.example/mcp");
  // Operator-configured scopes take precedence over the server's advertised set.
  assert.equal(url.searchParams.get("scope"), "issues:read");
  assert.ok(url.searchParams.get("code_challenge"));
  assert.ok(attempt);
  assert.equal((attempt as ProjectMcpOAuthAttempt).clientSecret, null);
  assert.equal(JSON.stringify(result).includes("verifier-value"), false);
});

test("OAuth completion consumes the PKCE attempt and stores the token without exposing it", async () => {
  let server = oauthServer();
  const repository = {
    get: async () => server,
    update: async (next: ProjectMcpServer) => {
      server = next;
      return next;
    },
  } as unknown as ProjectMcpServerRepository;
  const service = createProjectMcpOAuthService({
    repository,
    attempts: {
      create: async () => {},
      consume: async () => ({
        projectId: server.projectId,
        serverId: server.id,
        serverUrl: server.url,
        stateHash: "hash",
        codeVerifier: "verifier",
        redirectUri: "https://api.superlog.sh/api/agent-mcp-oauth/callback",
        clientId: "client",
        clientSecret: null,
        tokenEndpoint: "https://auth.example/token",
        authorizationServer: "https://auth.example",
        resource: server.url,
        scopes: ["issues:read"],
        expiresAt: new Date("2026-07-14T10:10:00.000Z"),
      }),
    },
    http: {
      discover: async () => {
        throw new Error("not called");
      },
      register: async () => {
        throw new Error("not called");
      },
      exchange: async (input) => {
        assert.equal(input.codeVerifier, "verifier");
        assert.equal(input.resource, server.url);
        return {
          accessToken: "[REDACTED]",
          refreshToken: "[REDACTED]",
          expiresInSeconds: 3600,
          scope: "issues:read issues:write",
        };
      },
      refresh: async () => {
        throw new Error("not called");
      },
      clientCredentials: async () => {
        throw new Error("not called");
      },
    },
    now: () => new Date("2026-07-14T10:00:00.000Z"),
  });

  const result = await service.complete({ state: "state", code: "code" });

  assert.equal(result.auth.type, "oauth");
  if (result.auth.type !== "oauth") return;
  assert.equal(result.auth.status, "connected");
  assert.equal(result.auth.accessToken, "access-secret");
  assert.deepEqual(result.auth.scopes, ["issues:read", "issues:write"]);
});

test("OAuth completion rejects a grant started before the server configuration changed", async () => {
  let server = oauthServer();
  const originalUrl = server.url;
  let exchangeCalled = false;
  const repository = {
    get: async () => server,
    update: async (next: ProjectMcpServer) => {
      server = next;
      return next;
    },
  } as unknown as ProjectMcpServerRepository;
  const service = createProjectMcpOAuthService({
    repository,
    attempts: {
      create: async () => {},
      consume: async () => ({
        projectId: server.projectId,
        serverId: server.id,
        serverUrl: originalUrl,
        stateHash: "hash",
        codeVerifier: "verifier",
        redirectUri: "https://api.superlog.sh/api/agent-mcp-oauth/callback",
        clientId: "client",
        clientSecret: null,
        tokenEndpoint: "https://auth.example/token",
        authorizationServer: "https://auth.example",
        resource: originalUrl,
        scopes: ["issues:read"],
        expiresAt: new Date("2026-07-14T10:10:00.000Z"),
      }),
    },
    http: {
      discover: async () => {
        throw new Error("not called");
      },
      register: async () => {
        throw new Error("not called");
      },
      exchange: async () => {
        exchangeCalled = true;
        throw new Error("must not exchange");
      },
      refresh: async () => {
        throw new Error("not called");
      },
      clientCredentials: async () => {
        throw new Error("not called");
      },
    },
    now: () => new Date("2026-07-14T10:00:00.000Z"),
  });

  server = { ...server, url: "https://replacement.example/mcp" };

  await assert.rejects(
    service.complete({ state: "state", code: "code" }),
    /configuration changed/i,
  );
  assert.equal(exchangeCalled, false);
});

test("expired OAuth access tokens are refreshed and rotated refresh tokens are retained", async () => {
  let server = oauthServer();
  if (server.auth.type !== "oauth") throw new Error("bad fixture");
  server = {
    ...server,
    auth: {
      ...server.auth,
      status: "connected",
      clientId: "client",
      clientSecret: "[REDACTED]",
      accessToken: "old-access",
      refreshToken: "old-refresh",
      expiresAt: new Date("2026-07-14T10:00:30.000Z"),
      tokenEndpoint: "https://auth.example/token",
      resource: server.url,
    },
  };
  const repository = {
    get: async () => server,
    update: async (next: ProjectMcpServer) => {
      server = next;
      return next;
    },
  } as unknown as ProjectMcpServerRepository;
  const service = createProjectMcpOAuthService({
    repository,
    attempts: { create: async () => {}, consume: async () => null },
    http: {
      discover: async () => {
        throw new Error("not called");
      },
      register: async () => {
        throw new Error("not called");
      },
      exchange: async () => {
        throw new Error("not called");
      },
      refresh: async (input) => {
        assert.equal(input.refreshToken, "old-refresh");
        return {
          accessToken: "new-access",
          refreshToken: "new-refresh",
          expiresInSeconds: 1800,
          scope: null,
        };
      },
      clientCredentials: async () => {
        throw new Error("not called");
      },
    },
    now: () => new Date("2026-07-14T10:00:00.000Z"),
  });

  const result = await service.ensureFresh({
    projectId: server.projectId,
    serverId: server.id,
  });

  assert.equal(result.auth.type, "oauth");
  if (result.auth.type !== "oauth") return;
  assert.equal(result.auth.accessToken, "new-access");
  assert.equal(result.auth.refreshToken, "new-refresh");
});

test("OAuth client credentials is accepted only when the authorization server advertises it", async () => {
  let server = oauthServer();
  if (server.auth.type !== "oauth") throw new Error("bad fixture");
  server = {
    ...server,
    auth: {
      ...server.auth,
      grantType: "client_credentials",
      scopes: [],
      clientId: "service-client",
      clientSecret: "[REDACTED]",
    },
  };
  const repository = {
    get: async () => server,
    update: async (next: ProjectMcpServer) => {
      server = next;
      return next;
    },
  } as unknown as ProjectMcpServerRepository;
  const service = createProjectMcpOAuthService({
    repository,
    attempts: { create: async () => {}, consume: async () => null },
    http: {
      discover: async () => ({
        authorizationServer: "https://auth.example",
        authorizationEndpoint: "https://auth.example/authorize",
        tokenEndpoint: "https://auth.example/token",
        registrationEndpoint: null,
        resource: server.url,
        codeChallengeMethods: ["S256"],
        grantTypes: ["client_credentials"],
        scopesSupported: ["service:read"],
      }),
      register: async () => {
        throw new Error("not called");
      },
      exchange: async () => {
        throw new Error("not called");
      },
      refresh: async () => {
        throw new Error("not called");
      },
      clientCredentials: async (input) => {
        assert.equal(input.clientId, "service-client");
        assert.equal(input.resource, server.url);
        assert.deepEqual(input.scopes, ["service:read"]);
        return {
          accessToken: "[REDACTED]",
          refreshToken: null,
          expiresInSeconds: 600,
          scope: null,
        };
      },
    },
    now: () => new Date("2026-07-14T10:00:00.000Z"),
  });

  const result = await service.connectClientCredentials({
    projectId: server.projectId,
    serverId: server.id,
    actorUserId: "user-1",
  });

  assert.equal(result.auth.type, "oauth");
  if (result.auth.type !== "oauth") return;
  assert.equal(result.auth.status, "connected");
  assert.equal(result.auth.accessToken, "service-access");
  assert.deepEqual(result.auth.scopes, ["service:read"]);
});

test("OAuth start requests the server's advertised scopes when none are configured", async () => {
  let server = oauthServer();
  server = {
    ...server,
    auth: { ...server.auth, type: "oauth", scopes: [] } as ProjectMcpServer["auth"],
  };
  let attempt: ProjectMcpOAuthAttempt | null = null;
  const repository = {
    get: async () => server,
    update: async (next: ProjectMcpServer) => {
      server = next;
      return next;
    },
  } as unknown as ProjectMcpServerRepository;
  const service = createProjectMcpOAuthService({
    repository,
    attempts: {
      create: async (value) => {
        attempt = value;
      },
      consume: async () => null,
    },
    http: {
      discover: async () => ({
        authorizationServer: "https://auth.example",
        authorizationEndpoint: "https://auth.example/authorize",
        tokenEndpoint: "https://auth.example/token",
        registrationEndpoint: "https://auth.example/register",
        resource: "https://linear.example/mcp",
        codeChallengeMethods: ["S256"],
        grantTypes: ["authorization_code", "refresh_token"],
        scopesSupported: ["projects:read", "database:read"],
      }),
      register: async (_registrationEndpoint, _redirectUri, scopes) => {
        assert.deepEqual(scopes, ["projects:read", "database:read"]);
        return { clientId: "dynamic-client", clientSecret: null };
      },
      exchange: async () => {
        throw new Error("not called");
      },
      refresh: async () => {
        throw new Error("not called");
      },
      clientCredentials: async () => {
        throw new Error("not called");
      },
    },
    randomToken: (() => {
      const values = ["state-value", "verifier-value"];
      return () => values.shift() ?? "unused";
    })(),
    now: () => new Date("2026-07-14T10:00:00.000Z"),
  });

  const result = await service.start({
    projectId: "project-1",
    serverId: "server-1",
    actorUserId: "user-1",
    redirectUri: "https://api.superlog.sh/api/agent-mcp-oauth/callback",
  });

  const url = new URL(result.authorizationUrl);
  assert.equal(url.searchParams.get("scope"), "projects:read database:read");
  // The advertised set is persisted so a token response without `scope` still
  // records what was actually requested.
  assert.deepEqual((attempt as unknown as ProjectMcpOAuthAttempt).scopes, [
    "projects:read",
    "database:read",
  ]);
  assert.equal(server.auth.type, "oauth");
  if (server.auth.type === "oauth") {
    assert.deepEqual(server.auth.scopes, ["projects:read", "database:read"]);
  }
});

test("OAuth discovery prefers the protected-resource scopes_supported over the auth server's", async () => {
  const json = (body: unknown, init?: ResponseInit) =>
    new Response(JSON.stringify(body), {
      status: 200,
      headers: { "content-type": "application/json" },
      ...init,
    });
  const fakeFetch = (async (input: URL | string | Request) => {
    const target = input.toString();
    if (target === "https://mcp.example/mcp") {
      return new Response(null, { status: 401 });
    }
    if (target === "https://mcp.example/.well-known/oauth-protected-resource/mcp") {
      return json({
        resource: "https://mcp.example/mcp?read_only=true",
        authorization_servers: ["https://as.example"],
        scopes_supported: ["projects:read", "database:read"],
      });
    }
    if (target === "https://as.example/.well-known/oauth-authorization-server") {
      return json({
        authorization_endpoint: "https://as.example/authorize",
        token_endpoint: "https://as.example/token",
        code_challenge_methods_supported: ["S256"],
        grant_types_supported: ["authorization_code"],
        // The auth server advertises writes too; discovery must not pick these
        // up when the protected resource has already narrowed the set.
        scopes_supported: ["projects:read", "projects:write", "database:write"],
      });
    }
    return new Response(null, { status: 404 });
  }) as unknown as typeof fetch;

  const discovery =
    await createFetchProjectMcpOAuthHttp(fakeFetch).discover("https://mcp.example/mcp");

  assert.deepEqual(discovery.scopesSupported, ["projects:read", "database:read"]);
});

test("OAuth discovery does not default to authorization-server scopes", async () => {
  const json = (body: unknown) =>
    new Response(JSON.stringify(body), {
      status: 200,
      headers: { "content-type": "application/json" },
    });
  const fakeFetch = (async (input: URL | string | Request) => {
    const target = input.toString();
    if (target === "https://mcp.example/mcp") {
      return new Response(null, { status: 401 });
    }
    if (target === "https://mcp.example/.well-known/oauth-protected-resource/mcp") {
      return json({
        resource: "https://mcp.example/mcp",
        authorization_servers: ["https://as.example"],
      });
    }
    if (target === "https://as.example/.well-known/oauth-authorization-server") {
      return json({
        authorization_endpoint: "https://as.example/authorize",
        token_endpoint: "https://as.example/token",
        code_challenge_methods_supported: ["S256"],
        grant_types_supported: ["authorization_code"],
        scopes_supported: ["projects:read", "projects:write", "admin"],
      });
    }
    return new Response(null, { status: 404 });
  }) as unknown as typeof fetch;

  const discovery =
