    ["awaiting_events", "resume"],
    ["resuming", "resume"],
    ["pr_retry_queued", "retry_pr_delivery"],
  ];
  for (const [state, expected] of states) {
    const fb = fakeBoss();
    const { deps, calls } = makeDeps({ loadRun: async (id) => runOf(id, state) });
    await registerAgentRunQueue(fb.boss, deps);
